# name: test/sql/connect_transactions.test
# description: once CONNECT-ed, BEGIN/COMMIT/ROLLBACK are forwarded verbatim and are the remote's to decide
# group: [sql]

include test/template/quack_setup.test_template

statement ok
attach {server} as q (token 'asdf')

statement ok
CONNECT q;

# BEGIN is shipped as-is. It used to land inside a synthesized per-statement transaction,
# so the remote refused it (and the matching COMMIT/ROLLBACK arrived after that transaction
# had already closed).
statement ok
BEGIN;

statement ok
CREATE TABLE connect_tx(i INT);

statement ok
INSERT INTO connect_tx VALUES (42);

# the open remote transaction sees its own uncommitted rows
query I
SELECT i FROM connect_tx;
----
42

statement ok
ROLLBACK;

# the rollback was the remote's: the table never landed
statement error
SELECT i FROM connect_tx;
----
connect_tx

# ... and a committed one does land
statement ok
BEGIN;

statement ok
CREATE TABLE connect_tx(i INT);

statement ok
INSERT INTO connect_tx VALUES (7);

statement ok
COMMIT;

query I
SELECT i FROM connect_tx;
----
7

statement ok
DROP TABLE connect_tx;

statement ok
DISCONNECT;

statement ok
detach q;

include test/template/quack_teardown.test_template

#include "storage/quack_transaction_manager.hpp"
#include "storage/quack_catalog.hpp"

#include <exception>

namespace duckdb {

QuackTransactionManager::QuackTransactionManager(AttachedDatabase &db_p, QuackCatalog &quack_catalog_p)
    : TransactionManager(db_p), quack_catalog(quack_catalog_p) {
}

Transaction &QuackTransactionManager::StartTransaction(ClientContext &context) {
	auto transaction = make_uniq<QuackTransaction>(quack_catalog, *this, context);
	transaction->Start();
	auto &result = *transaction;
	lock_guard<mutex> l(transaction_lock);
	transactions[result] = std::move(transaction);
	return result;
}
ErrorData QuackTransactionManager::CommitTransaction(ClientContext &context, Transaction &transaction) {
	auto &quack_transaction = transaction.Cast<QuackTransaction>();
	ErrorData error;
	try {
		quack_transaction.Commit();
	} catch (const std::exception &ex) {
		error = ErrorData(ex);
	} catch (...) {
		error = ErrorData("Server COMMIT failed");
	}
	if (error.HasError()) {
		quack_catalog.InvalidateIfChangedSince(quack_transaction.StartVersion());
	}
	DestroyTransaction(transaction);
	return error;
}

void QuackTransactionManager::RollbackTransaction(Transaction &transaction) {
	auto &quack_transaction = transaction.Cast<QuackTransaction>();
	std::exception_ptr failure;
	try {
		quack_transaction.Rollback();
	} catch (...) {
		failure = std::current_exception();
	}
	quack_catalog.InvalidateIfChangedSince(quack_transaction.StartVersion());
	DestroyTransaction(transaction);
	if (failure) {
		std::rethrow_exception(failure);
	}
}

void QuackTransactionManager::DestroyTransaction(Transaction &transaction) {
	unique_ptr<QuackTransaction> removed_transaction;
	{
		lock_guard<mutex> guard(transaction_lock);
		auto entry = transactions.find(transaction);
		D_ASSERT(entry != transactions.end());
		removed_transaction = std::move(entry->second);
		transactions.erase(entry);
	}
}

void QuackTransactionManager::Checkpoint(ClientContext &context, bool force) {
	throw NotImplementedException("Checkpoint not implemented yet");
}

} // namespace duckdb

#include "storage/quack_transaction.hpp"

#include "duckdb/common/printer.hpp"
#include "duckdb/main/client_context.hpp"
#include "storage/quack_catalog.hpp"

namespace duckdb {

QuackTransaction::QuackTransaction(QuackCatalog &quack_catalog_p, TransactionManager &manager_p,
                                   ClientContext &context_p)
    : Transaction(manager_p, context_p), quack_catalog(quack_catalog_p),
      transaction_state(QuackTransactionState::TRANSACTION_NOT_YET_STARTED),
      start_version(quack_catalog_p.InvalidatedVersion()) {
}

QuackTransaction::~QuackTransaction() {
}

void QuackTransaction::Start() {
	transaction_state = QuackTransactionState::TRANSACTION_NOT_YET_STARTED;
}

void QuackTransaction::ForceStart() {
	if (transaction_state == QuackTransactionState::TRANSACTION_NOT_YET_STARTED) {
		transaction_state = QuackTransactionState::TRANSACTION_STARTED;
		Query("BEGIN TRANSACTION");
	}
}

void QuackTransaction::Commit() {
	if (transaction_state == QuackTransactionState::TRANSACTION_STARTED) {
		transaction_state = QuackTransactionState::TRANSACTION_FINISHED;
		Query("COMMIT");
	}
}

void QuackTransaction::Rollback() {
	if (transaction_state == QuackTransactionState::TRANSACTION_STARTED) {
		transaction_state = QuackTransactionState::TRANSACTION_FINISHED;
		Query("ROLLBACK");
	}
}

void QuackTransaction::Retain(shared_ptr<QuackSchemaSet> snapshot) {
	lock_guard<mutex> guard(retained_lock);
	if (retained_snapshots.empty() || retained_snapshots.back() != snapshot) {
		retained_snapshots.push_back(std::move(snapshot));
	}
}

optional_ptr<CatalogEntry> QuackTransaction::Retain(unique_ptr<CatalogEntry> entry) {
	lock_guard<mutex> guard(retained_lock);
	retained_entries.push_back(std::move(entry));
	return retained_entries.back().get();
}

QuackTransaction &QuackTransaction::Get(ClientContext &context, Catalog &catalog) {
	return Transaction::Get(context, catalog).Cast<QuackTransaction>();
}

QuackTransaction &QuackTransaction::Get(CatalogTransaction transaction) {
	if (!transaction.transaction) {
		throw InternalException("No transaction!?");
	}
	return transaction.transaction->Cast<QuackTransaction>();
}

unique_ptr<ColumnDataCollection> QuackTransaction::Query(const string &query) {
	ForceStart();
	auto context_ref = context.lock();
	if (!context_ref) {
		// context has been destroyed - silently ignore the query
		return nullptr;
	}
	return quack_catalog.ExecuteCommandInternal(*context_ref, query);
}

} // namespace duckdb

